// Parse Ollama JSON response
const response = $input.first().json;
let text = response.response || response.body?.response || '';
// Extract JSON from response
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  try {
    const data = JSON.parse(jsonMatch[0]);
    return [{ json: data }];
  } catch(e) {
    return [{ json: { error: JSON.stringify(e), raw: text } }];
  }
}
return [{ json: { error: 'No JSON found', raw: text } }];
